        PoemEntity("Itsy Bitsy Spider", "#06B6D4", "[\"The itsy bitsy spider,\",\"Climbed up the water spout;\",\"Down came the rain,\",\"And washed the spider out.\",\"Out came the sun,\",\"And dried up all the rain;\",\"And the itsy bitsy spider,\",\"Climbed up the spout again.\",\"The itsy bitsy spider,\",\"Climbed up the kitchen wall;\",\"Swoosh went the fan,\",\"And made the spider fall.\",\"Off went the fan,\",\"No longer did it blow;\",\"So the itsy bitsy spider,\",\"Back up the wall did go.\"]"),
        PoemEntity("Wheels on the Bus", "#0EA5E9", "[\"The wheels on the bus go round and round,\",\"Round and round, round and round;\",\"The wheels on the bus go round and round,\",\"All through the town.\",\"The wipers on the bus go swish, swish, swish,\",\"Swish, swish, swish, swish, swish, swish;\",\"The wipers on the bus go swish, swish, swish,\",\"All through the town.\",\"The horn on the bus goes beep, beep, beep,\",\"Beep, beep, beep, beep, beep, beep;\",\"The horn on the bus goes beep, beep, beep,\",\"All through the town.\",\"The doors on the bus go open and shut,\",\"Open and shut, open and shut;\",\"The doors on the bus go open and shut,\",\"All through the town.\",\"The babies on the bus go waa, waa, waa,\",\"Waa, waa, waa, waa, waa, waa;\",\"The babies on the bus go waa, waa, waa,\",\"All through the town.\",\"The parents on the bus go shh, shh, shh,\",\"Shh, shh, shh, shh, shh, shh;\",\"The parents on the bus go shh, shh, shh,\",\"All through the town.\"]")
